param([string]$CacheRoot=(Join-Path $PSScriptRoot "..\\.cache\\cef-windows-build"),[switch]$Force)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;$v="152.0.6+g708dc14+chromium-152.0.7977.83";$n="cef_binary_${v}_windows64_minimal.tar.bz2";$u="https://cef-builds.spotifycdn.com/$n";$s256="DB3E0751979C3CB3068F732ED4F0EF12ADE69D183D98CEEE120AD08C8D00F74C";$s1="E5E3020627F4528BD43E22F4C4970000B0458E99";$c=[IO.Path]::GetFullPath($CacheRoot);$r=Join-Path $c ($n-replace "\\.tar\\.bz2$","")
if(!$Force -and (Test-Path "$r\\include\\cef_app.h") -and (Test-Path "$r\\Release\\bootstrap.exe")){$r;exit 0};New-Item -ItemType Directory -Force $c|Out-Null;$a=Join-Path $c $n;if($Force -or !(Test-Path $a)){Invoke-WebRequest $u -OutFile "$a.part" -UseBasicParsing;Move-Item -Force "$a.part" $a};if((Get-FileHash -LiteralPath $a -Algorithm SHA256).Hash -ne $s256 -or (Get-FileHash -LiteralPath $a -Algorithm SHA1).Hash -ne $s1){Remove-Item -Force $a;throw "CEF checksum verification failed."};$t=Join-Path $c "extract-$PID";Remove-Item -Recurse -Force $t -ErrorAction Ignore;New-Item -ItemType Directory $t|Out-Null;try{tar.exe -xjf $a -C $t;if($LASTEXITCODE){throw "CEF extraction failed."};$x=Join-Path $t ($n-replace "\\.tar\\.bz2$","");foreach($p in "CMakeLists.txt","include\\cef_app.h","Release\\bootstrap.exe","Resources\\locales"){if(!(Test-Path "$x\\$p")){throw "CEF misses $p"}};Remove-Item -Recurse -Force $r -ErrorAction Ignore;Move-Item $x $r}finally{Remove-Item -Recurse -Force $t -ErrorAction Ignore};$r